-- Fewer repeats of the customer's first name in a diagnosis.
-- Until now four paragraphs of every diagnosis began with the name (the result, the text of the secondary
-- style, the paragraph of the pair and the guidance). Now only the result and the guidance carry it: the
-- text of the secondary style and the 30 pair paragraphs lose the leading "{nome}, " and keep the rest.
-- Source: docs/RF-07-diagnosis-content-and-pdf-generation/content-source.json (generated by scripts/generate-content-seed.mjs).
-- Migrations 11 and 14 stay as released; this one updates 36 templates of version 1 in place. A diagnosis
-- already generated keeps the text it was generated with.

do $update$
declare
  v_count integer;
begin
  with changes(kind, style, secondary_style, block, body) as (values
    ('style_block', 'esportivo_natural', null, 'secondary', 'O seu segundo estilo é o Esportivo/Natural. Ele traz para o seu visual o conforto, a praticidade e a naturalidade: é a parte de você que gosta de se vestir de um jeito leve, sem esforço aparente, e de se sentir à vontade em qualquer lugar. Esse toque suaviza o seu estilo principal e faz a sua imagem comunicar simplicidade e autenticidade.'),
    ('style_block', 'tradicional', null, 'secondary', 'O seu segundo estilo é o Tradicional. Ele traz para o seu visual a discrição, a organização e o gosto pelo que é atemporal: é a parte de você que prefere peças clássicas, de qualidade, que nunca saem de moda. Esse toque dá base e equilíbrio ao seu estilo principal e faz a sua imagem comunicar seriedade e confiança.'),
    ('style_block', 'elegante', null, 'secondary', 'O seu segundo estilo é o Elegante. Ele traz para o seu visual o refinamento e a sofisticação: é a parte de você que gosta de qualidade, de cortes impecáveis e de um visual harmonioso e bem cuidado. Esse toque dá acabamento ao seu estilo principal e faz a sua imagem comunicar classe e bom gosto.'),
    ('style_block', 'romantico', null, 'secondary', 'O seu segundo estilo é o Romântico. Ele traz para o seu visual a delicadeza, a feminilidade e os detalhes suaves: é a parte de você que gosta de tecidos fluidos e de tons delicados. Esse toque suaviza o seu estilo principal e faz a sua imagem comunicar gentileza e charme.'),
    ('style_block', 'criativo', null, 'secondary', 'O seu segundo estilo é o Criativo. Ele traz para o seu visual a originalidade e a liberdade de se expressar: é a parte de você que gosta de misturar cores, texturas e estampas. Esse toque dá personalidade ao seu estilo principal e faz a sua imagem comunicar curiosidade e alegria.'),
    ('style_block', 'dramatico', null, 'secondary', 'O seu segundo estilo é o Dramático. Ele traz para o seu visual o impacto e a presença marcante: é a parte de você que gosta de contrastes e de linhas definidas. Esse toque dá força ao seu estilo principal e faz a sua imagem comunicar ousadia e determinação.'),
    ('pair_paragraph', 'esportivo_natural', 'tradicional', null, 'A naturalidade do Esportivo/Natural encontra a sobriedade do Tradicional: o seu visual é confortável sem ser descuidado e organizado sem ser rígido. Combine peças clássicas de corte reto com tecidos leves, como uma camisa de algodão com calça de alfaiataria e tênis branco, e você terá looks que servem do trabalho ao fim de semana.'),
    ('pair_paragraph', 'esportivo_natural', 'elegante', null, 'A leveza do Esportivo/Natural ganha refinamento com o Elegante. Seu caminho é o conforto sofisticado: tecidos nobres em modelagens soltas, tons neutros e poucos detalhes bem escolhidos. Uma calça fluida com camiseta de ótimo caimento e um sapato de couro limpo mostram que simples e elegante podem ser a mesma coisa.'),
    ('pair_paragraph', 'esportivo_natural', 'romantico', null, 'O Esportivo/Natural dá praticidade ao seu lado Romântico, e o resultado é um feminino descontraído e muito autêntico. Misture peças delicadas, como uma blusa de renda ou um vestido floral, com itens casuais, como jaqueta jeans e tênis, para um visual suave e sem esforço.'),
    ('pair_paragraph', 'esportivo_natural', 'criativo', null, 'A espontaneidade do Esportivo/Natural se une à originalidade do Criativo em looks descontraídos e cheios de personalidade. Use uma base confortável e acrescente um toque inusitado: uma estampa diferente, um acessório artesanal ou uma cor viva faz toda a diferença sem perder a leveza.'),
    ('pair_paragraph', 'esportivo_natural', 'dramatico', null, 'O Esportivo/Natural suaviza a força do seu lado Dramático, e o resultado é um impacto que parece natural. Aposte em linhas retas e contrastes marcantes em tecidos confortáveis, como um conjunto de alfaiataria preto de modelagem folgada com uma camiseta branca e um sapato de design forte.'),
    ('pair_paragraph', 'tradicional', 'esportivo_natural', null, 'A base clássica do Tradicional ganha leveza com o Esportivo/Natural. Você pode manter a sobriedade das peças de qualidade e descontrair o conjunto: um blazer azul-marinho sobre camiseta de algodão, calça reta e mocassim formam um look seguro, atual e confortável.'),
    ('pair_paragraph', 'tradicional', 'elegante', null, 'O Tradicional e o Elegante caminham juntos no seu guarda-roupa: a base clássica ganha acabamento refinado. Invista em alfaiataria impecável, tecidos nobres e cores sóbrias bem combinadas, como o conjunto de camisa de seda, saia midi e scarpin, que transmite credibilidade e classe.'),
    ('pair_paragraph', 'tradicional', 'romantico', null, 'A discrição do Tradicional encontra a delicadeza do Romântico. Você pode manter as formas clássicas e acrescentar suavidade: um vestido chemisier de estampa floral miúda, um cardigã em tom claro e um colar de pérolas compõem um visual doce e respeitável.'),
    ('pair_paragraph', 'tradicional', 'criativo', null, 'A estrutura do Tradicional dá base ao seu lado Criativo, e a combinação é muito interessante. Construa os looks com peças clássicas e deixe a originalidade aparecer em um detalhe: um lenço estampado, um colar artesanal ou um sapato de cor diferente renovam o clássico sem desorganizá-lo.'),
    ('pair_paragraph', 'tradicional', 'dramatico', null, 'O Tradicional dá o equilíbrio e o Dramático dá a presença. Seus melhores looks têm linhas clássicas com contrastes bem definidos: um blazer estruturado em cor intensa, camisa branca impecável e calça de alfaiataria escura comunicam autoridade com elegância.'),
    ('pair_paragraph', 'elegante', 'esportivo_natural', null, 'A sofisticação do Elegante aparece, no seu caso, de um jeito leve e despretensioso. Escolha peças de qualidade em tons neutros e modelagens fluidas, como um conjunto de linho, e use o calçado para ajustar o tom: o sapato de couro formaliza, a sandália ou o tênis limpo descontraem.'),
    ('pair_paragraph', 'elegante', 'tradicional', null, 'O Elegante lidera o seu estilo e o Tradicional garante a base sólida. Os cortes clássicos recebem acabamento refinado: tecidos nobres, caimento impecável e uma cartela de poucas cores. Um vestido de linhas retas com blazer e scarpin é um uniforme de sucesso para você.'),
    ('pair_paragraph', 'elegante', 'romantico', null, 'O refinamento do Elegante e a delicadeza do Romântico formam uma feminilidade sofisticada. Prefira tecidos fluidos de qualidade, cores suaves e detalhes sutis, como um decote delicado ou uma manga com leve volume, que valorizam a silhueta sem excesso de enfeites.'),
    ('pair_paragraph', 'elegante', 'criativo', null, 'O Elegante organiza e o Criativo surpreende, e o resultado é uma elegância com assinatura própria. Mantenha cortes impecáveis e cores harmoniosas e escolha um elemento original por look, como um brinco escultural, uma estampa autoral ou uma textura diferente.'),
    ('pair_paragraph', 'elegante', 'dramatico', null, 'O Elegante e o Dramático se encontram em um visual poderoso e refinado. Linhas retas, cortes precisos e contrastes bem escolhidos funcionam muito bem: um vestido midi de cor intensa, um blazer estruturado e um acessório escultural dão presença sem perder a classe.'),
    ('pair_paragraph', 'romantico', 'esportivo_natural', null, 'A delicadeza do Romântico ganha descontração com o Esportivo/Natural. Você pode usar peças suaves no dia a dia sem parecer produzida: uma saia plissada com camiseta básica e tênis, ou um vestido floral com jaqueta jeans, resultam em um visual doce e confortável.'),
    ('pair_paragraph', 'romantico', 'tradicional', null, 'O Romântico traz a doçura e o Tradicional traz o bom senso. Escolha formas clássicas em tons suaves e tecidos delicados, como uma blusa de laço com saia midi e cardigã, e acessórios discretos, como brincos de pérola, para um visual feminino e atemporal.'),
    ('pair_paragraph', 'romantico', 'elegante', null, 'O Romântico lidera e o Elegante refina o conjunto. Você pode usar rendas, fluidez e tons suaves com acabamento primoroso: tecidos de qualidade, cortes bem ajustados e poucos detalhes de impacto fazem a sua delicadeza parecer sofisticada.'),
    ('pair_paragraph', 'romantico', 'criativo', null, 'A ternura do Romântico se mistura à originalidade do Criativo em um feminino cheio de fantasia. Explore estampas florais incomuns, cores suaves combinadas de forma inesperada e acessórios artesanais, deixando um elemento como protagonista para o visual não ficar carregado.'),
    ('pair_paragraph', 'romantico', 'dramatico', null, 'O Romântico e o Dramático formam um contraste cheio de charme: a doçura que encanta e a força que marca presença. Experimente combinar um vestido fluido com uma jaqueta estruturada de couro, ou um laço delicado com um batom e um sapato de impacto.'),
    ('pair_paragraph', 'criativo', 'esportivo_natural', null, 'A imaginação do Criativo ganha liberdade com o Esportivo/Natural. Seus looks funcionam quando são confortáveis e divertidos: peças-base soltas, com um toque de cor ou de estampa, e acessórios artesanais que contam algo sobre você, sem pesar na rotina.'),
    ('pair_paragraph', 'criativo', 'tradicional', null, 'O Criativo conduz e o Tradicional organiza. Use o clássico como tela para a sua originalidade: um blazer de alfaiataria com estampa inesperada na blusa, ou uma calça reta com um colar autoral. Assim as suas ideias aparecem com ordem e boa proporção.'),
    ('pair_paragraph', 'criativo', 'elegante', null, 'O Criativo e o Elegante produzem uma sofisticação artística. Escolha cortes limpos e tecidos nobres e permita-se uma estampa, uma cor ou um acessório de assinatura. Menos peças, mais autorais, é a fórmula para você brilhar sem parecer excessiva.'),
    ('pair_paragraph', 'criativo', 'romantico', null, 'O Criativo e o Romântico se unem em um visual poético e cheio de fantasia. Brinque com estampas delicadas, tons suaves em misturas inesperadas e detalhes como laços e bordados, e use acessórios artesanais para manter a sua originalidade em evidência.'),
    ('pair_paragraph', 'criativo', 'dramatico', null, 'O Criativo e o Dramático formam uma combinação de grande impacto e muita personalidade. Aposte em formas e cores intensas com linhas fortes, como uma peça assimétrica em preto com um acessório escultural colorido, e deixe um único ponto de destaque comandar o look.'),
    ('pair_paragraph', 'dramatico', 'esportivo_natural', null, 'A força do Dramático ganha naturalidade com o Esportivo/Natural. Seus looks funcionam com linhas retas e contrastes simples em tecidos confortáveis: um conjunto escuro de modelagem solta, uma camisa branca ampla e um tênis ou bota de design forte mostram presença sem rigidez.'),
    ('pair_paragraph', 'dramatico', 'tradicional', null, 'O Dramático dá impacto e o Tradicional garante a estrutura. Os cortes clássicos aparecem com cores intensas e contrastes marcados: um blazer escuro com camisa branca e uma saia lápis de couro formam um conjunto de autoridade e credibilidade.'),
    ('pair_paragraph', 'dramatico', 'elegante', null, 'O Dramático lidera e o Elegante lapida. Mantenha as linhas fortes, as cores intensas e o contraste, e acrescente o refinamento dos tecidos nobres e dos acabamentos perfeitos. Um vestido estruturado em cor profunda com um acessório escultural resume o seu poder de presença.'),
    ('pair_paragraph', 'dramatico', 'romantico', null, 'O Dramático e o Romântico se equilibram: força e delicadeza no mesmo visual. Use linhas fortes com tecidos macios, como um vestido justo com detalhe de renda, ou combine uma peça estruturada com um acessório delicado para suavizar o impacto.'),
    ('pair_paragraph', 'dramatico', 'criativo', null, 'O Dramático e o Criativo formam um estilo ousado e original. Aposte em contrastes de cor, texturas e formas marcantes, com um elemento inusitado por look: um casaco longo de corte diferente, um colar escultural ou uma estampa gráfica de impacto.')
  )
  update public.content_templates t
     set body = c.body
    from changes c, public.content_versions v
   where v.version = 1
     and t.version_id = v.id
     and t.kind = c.kind
     and t.style = c.style
     and t.secondary_style is not distinct from c.secondary_style
     and t.block is not distinct from c.block;
  get diagnostics v_count = row_count;
  if v_count <> 36 then
    raise exception 'expected to update 36 templates, updated %', v_count;
  end if;
end
$update$;
